// 1. 用 Performance API 查看实际使用的协议版本
const entries = performance.getEntriesByName('https://example.com/api');
if (entries.length > 0) {
  console.log('协议:', entries[0].nextHopProtocol); // h2, h3, http/1.1
}

// 2. 连接优化提示（HTML head 中）
// DNS 预解析：减少 DNS 查询耗时
// <link rel="dns-prefetch" href="//cdn.example.com">
// 预连接：提前完成 DNS + TCP + TLS
// <link rel="preconnect" href="https://cdn.example.com">
// 预加载：告诉浏览器这个资源一定会用到
// <link rel="preload" href="/critical.css" as="style">

// 3. Service Worker 中判断协议版本做差异化策略
if ('serviceWorker' in navigator) {
  navigator.serviceWorker.register('/sw.js');
}

// sw.js 中可检查连接质量
// self.addEventListener('fetch', event => {
