//   // 根据资源类型和网络状态决定缓存策略
// });

// 4. Fetch API 发起请求并观察协议
fetch('https://example.com/data')
  .then(res => {
    // 浏览器会自动协商 HTTP/2 或 HTTP/3
    // 服务端通过 Alt-Svc 头声明支持 HTTP/3
    // Alt-Svc: h3=":443"; ma=86400
    return res.json();
  });

